  "gorsel": "<svg viewBox=\"0 0 267 60\" role=\"img\" aria-label=\"Ot, ren geyiği, kurt besin zinciri\"><defs><marker id=\"okfenbz019\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"8\" markerHeight=\"8\" orient=\"auto\"><path d=\"M0 0L10 5L0 10z\" fill=\"currentColor\"/></marker></defs><line x1=\"46\" y1=\"30\" x2=\"75\" y2=\"30\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#okfenbz019)\"/><line x1=\"176\" y1=\"30\" x2=\"205\" y2=\"30\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#okfenbz019)\"/><rect x=\"10\" y=\"15\" width=\"34\" height=\"30\" rx=\"7\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"1.2\"/><text x=\"27\" y=\"35\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">Ot</text><rect x=\"78\" y=\"15\" width=\"96\" height=\"30\" rx=\"7\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"1.2\"/><text x=\"126\" y=\"35\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">Ren geyiği</text><rect x=\"208\" y=\"15\" width=\"49\" height=\"30\" rx=\"7\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"1.2\"/><text x=\"232.5\" y=\"35\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">Kurt</text></svg>",
