  "gorsel": "<svg viewBox=\"0 0 292 162\" role=\"img\" aria-label=\"Ot, tavşan, fare, çakal ve baykuştan oluşan besin ağı\"><defs><marker id=\"okfenbz021\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"8\" markerHeight=\"8\" orient=\"auto\"><path d=\"M0 0L10 5L0 10z\" fill=\"currentColor\"/></marker></defs><line x1=\"47.0\" y1=\"70.6\" x2=\"96.0\" y2=\"45.0\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#okfenbz021)\"/><line x1=\"47.0\" y1=\"91.4\" x2=\"103.0\" y2=\"120.7\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#okfenbz021)\"/><line x1=\"166.0\" y1=\"43.1\" x2=\"218.0\" y2=\"66.7\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#okfenbz021)\"/><line x1=\"158.0\" y1=\"122.5\" x2=\"218.0\" y2=\"95.3\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#okfenbz021)\"/><line x1=\"158.0\" y1=\"135.0\" x2=\"214.0\" y2=\"135.0\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#okfenbz021)\"/><rect x=\"10\" y=\"66\" width=\"34\" height=\"30\" rx=\"7\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"1.2\"/><text x=\"27\" y=\"86\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">Ot</text><rect x=\"98\" y=\"12\" width=\"65\" height=\"30\" rx=\"7\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"1.2\"/><text x=\"130.5\" y=\"32\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">Tavşan</text><rect x=\"106\" y=\"120\" width=\"49\" height=\"30\" rx=\"7\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"1.2\"/><text x=\"130.5\" y=\"140\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">Fare</text><rect x=\"221\" y=\"66\" width=\"57\" height=\"30\" rx=\"7\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"1.2\"/><text x=\"249.5\" y=\"86\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">Çakal</text><rect x=\"217\" y=\"120\" width=\"65\" height=\"30\" rx=\"7\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"1.2\"/><text x=\"249.5\" y=\"140\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">Baykuş</text></svg>",
